$ErrorActionPreference='Stop'
$Root=Split-Path -Parent $PSScriptRoot;$Php='C:\laragon\bin\php\php-8.3.7-Win32-vs16-x64\php.exe';$Writer=Join-Path $Root 'scripts\launch_monitoring.php';$Log=Join-Path $Root 'logs\scheduler_monitoring_guarded.log';$RunDir=Join-Path $Root 'storage\runtime\monitoring-runs';$Lock=Join-Path $Root 'storage\runtime\monitoring-scheduler.lock';$Timeout=300
New-Item -ItemType Directory -Force -Path (Split-Path $Log),$RunDir | Out-Null;$Token=[guid]::NewGuid().ToString('N')
try{New-Item -ItemType Directory -Path $Lock -ErrorAction Stop|Out-Null;Set-Content (Join-Path $Lock 'owner') $Token -NoNewline}catch{Add-Content $Log "[$(Get-Date -Format o)] [SKIP] lock exists";exit 75}
$RunId="$(Get-Date -Format yyyyMMdd_HHmmss)_$Token";$Out=Join-Path $RunDir "$RunId.stdout.log";$Err=Join-Path $RunDir "$RunId.stderr.log";$Meta=Join-Path $RunDir "$RunId.meta.json"
try{if(!(Test-Path $Php)-or!(Test-Path $Writer)){throw 'runner dependency missing'};[ordered]@{run_id=$RunId;token=$Token;account=$env:USERNAME;working_directory=(Join-Path $Root 'dashboard');timeout_seconds=$Timeout;mode='monitoring'}|ConvertTo-Json|Set-Content $Meta;Add-Content $Log "[$(Get-Date -Format o)] [START] run_id=$RunId account=$env:USERNAME timeout=$Timeout";$p=Start-Process $Php -ArgumentList @($Writer) -WorkingDirectory (Join-Path $Root 'dashboard') -RedirectStandardOutput $Out -RedirectStandardError $Err -PassThru;Add-Content $Log "[$(Get-Date -Format o)] [CHILD] run_id=$RunId pid=$($p.Id) stdout=$Out stderr=$Err";$deadline=(Get-Date).AddSeconds($Timeout);while(!$p.HasExited){Start-Sleep 5;$p.Refresh();if((Get-Date)-ge$deadline){Add-Content $Log "[$(Get-Date -Format o)] [TIMEOUT] run_id=$RunId pid=$($p.Id)";exit 124}};$p.Refresh();$rc=[int]$p.ExitCode;Add-Content $Log "[$(Get-Date -Format o)] [END] run_id=$RunId pid=$($p.Id) exit_code=$rc";if($rc-ne 0){Add-Content $Log "[$(Get-Date -Format o)] [FAILED] run_id=$RunId"};exit $rc}catch{Add-Content $Log "[$(Get-Date -Format o)] [FAILED] run_id=$RunId error=$($_.Exception.Message)";exit 1}finally{$owner=Join-Path $Lock 'owner';if((Test-Path $owner)-and((Get-Content $owner -Raw).Trim() -eq $Token)){Remove-Item $Lock -Recurse -Force}}